/* Notifications, announcements, earnings, command palette, modal, bands, users */
  // v127: authenticated operations diagnostics. Results are deliberately ephemeral and contain no secrets.
  let portalHealthState = null;
  let portalHealthLoading = false;
  async function runPortalHealthCheck(){
    if(!isAdmin()) throw new Error('Label admin access required.');
    if(portalHealthLoading) return;
    portalHealthLoading=true; portalHealthState={startedAt:new Date().toISOString(),checks:[],loading:true}; render();
    try {
      const started=performance.now();
      const {data,error}=await sb.functions.invoke('portal-health',{body:{}});
      if(error) throw new Error(data?.error||error.message||'Backend diagnostics could not run.');
      if(!data||data.success!==true||!Array.isArray(data.checks)) throw new Error('The health service returned an unexpected response.');
      const backendMs=Math.round(performance.now()-started);
      const imagePaths=['/img/logo-64.png','/img/logo-128.png','/img/logo-192.png','/img/logo-512.png'];
      const probeImage=url=>new Promise(resolve=>{const img=new Image();let settled=false;const done=ok=>{if(settled)return;settled=true;clearTimeout(timer);resolve({name:url,ok});};const timer=setTimeout(()=>done(false),7000);img.onload=()=>done(img.naturalWidth>0);img.onerror=()=>done(false);img.src=url+'?health='+Date.now().toString(36);});
      const imageResults=await Promise.all(imagePaths.map(probeImage));
      const visibleImages=[...document.querySelectorAll('#main-content img')].filter(img=>img.complete).map(img=>({name:img.alt||img.currentSrc||img.src,ok:img.naturalWidth>0}));
      const allImages=[...imageResults,...visibleImages.filter(x=>!imagePaths.some(path=>x.name.includes(path)))];
      const imageFailures=allImages.filter(x=>!x.ok);
      portalHealthState={startedAt:new Date().toISOString(),backendMs,checks:[...data.checks,{key:'local_images',label:'Portal images',status:imageFailures.length?'warning':'ok',detail:imageFailures.length?`${imageFailures.length} image(s) failed or are still unavailable.`:`${imageResults.length} local logo assets loaded; ${visibleImages.length} rendered images inspected.`,failures:imageFailures.slice(0,12).map(x=>x.name)}],loading:false,summary:data.summary||{}};
      toast(imageFailures.length?'Diagnostics finished; some images need attention.':'Diagnostics finished. Review any configuration-only checks below.','success');
    } catch(e) { portalHealthState={startedAt:new Date().toISOString(),loading:false,error:String(e?.message||e),checks:[]}; toast('Diagnostics could not complete.','error'); }
    finally { portalHealthLoading=false; if(portalHealthState)portalHealthState.loading=false; render(); }
  }
  function portalHealthPanel(){
    const state=portalHealthState;
    const rows=(state?.checks||[]).map(c=>`<div class="health-check-row"><span class="health-state ${c.status==='ok'?'ok':c.status==='warning'?'warning':'failed'}" aria-hidden="true"></span><div class="health-check-copy"><strong>${esc(c.label||c.key)}</strong><p>${esc(c.detail||'No detail available.')}</p>${c.failures?.length?`<small>${c.failures.map(esc).join(' · ')}</small>`:''}</div><span class="health-state-label">${c.status==='ok'?'Healthy':c.status==='warning'?'Review':'Failed'}</span></div>`).join('');
    return `<section class="card v30-panel portal-health-panel"><div class="section-head"><div><p class="eyebrow">LIVE DIAGNOSTICS</p><h2>System health centre</h2><p class="muted">Checks live Supabase connectivity, core tables, storage buckets and configuration flags. It does not send email or reveal secrets.</p></div><button class="primary" data-action="portal-health" ${portalHealthLoading?'disabled aria-busy="true"':''}>${portalHealthLoading?'<span class="loading-spinner mini-spinner" aria-hidden="true"></span> Checking…':icon('refresh-cw',15)+' Run checks'}</button></div>${state?.error?`<div class="error-box">${esc(state.error)}</div>`:''}${state?.loading?`<div class="health-skeleton" role="status" aria-live="polite"><i></i><i></i><i></i><span>Checking connected services…</span></div>`:''}${rows?`<div class="health-check-list">${rows}</div><p class="muted health-footnote">Completed ${new Date(state.startedAt).toLocaleString(currentLocale())}${Number.isFinite(state.backendMs)?` · Backend round-trip ${state.backendMs} ms`:''}. Email and Turnstile checks confirm configuration only; delivery and challenge flows require separate end-to-end tests.</p>`:(!state?.loading&&!state?.error?'<div class="health-empty"><strong>No diagnostic run yet</strong><p>Run checks to test the live backend and portal assets.</p></div>':'')}</section>`;
  }

  async function loadNotes(){ try{ const r=await sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(50); if(r.error)throw r.error; inbox=r.data||[]; setWorkspaceDataWarning('notifications',null); }catch(error){ inbox=[]; setWorkspaceDataWarning('notifications','Notifications could not load. Your inbox may be incomplete.'); console.warn('Notifications unavailable',error); } }
  function ago(d){const s=(Date.now()-new Date(d))/1000;return s<60?'just now':s<3600?Math.floor(s/60)+'m ago':s<86400?Math.floor(s/3600)+'h ago':Math.floor(s/86400)+'d ago';}
