  let paletteReturnFocus=null;
  function openPal(){
    paletteReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
    let p=document.getElementById('palette');
    if(!p){
      p=document.createElement('div');p.id='palette';p.className='palette';
      p.innerHTML='<div class="palette-box"><input id="pal-q" placeholder="Search releases, bands, artists..." autocomplete="off"><div id="pal-res"></div></div>';
      document.body.appendChild(p);
      p.addEventListener('click',e=>{if(e.target===p||e.target.closest('[data-action]'))setTimeout(closePal,0);});
      p.querySelector('#pal-q').addEventListener('input',palSearch);
      // Delegate keyboard handling from the whole dialog so arrow navigation keeps
      // working after focus moves from the query input to a result button.
      p.addEventListener('keydown',e=>{
        const items=[...p.querySelectorAll('.pal-item')];
        if(e.key==='ArrowDown'||e.key==='ArrowUp'){
          e.preventDefault();if(!items.length)return;
          const current=items.indexOf(document.activeElement);
          const next=e.key==='ArrowDown'?(current+1)%items.length:(current<=0?items.length-1:current-1);
          items[next].focus();
        }else if(e.key==='Enter'){
          const active=document.activeElement;
          if(active instanceof HTMLElement&&active.classList.contains('pal-item'))return;
          e.preventDefault();items[0]?.click();
        }
      });
      p.setAttribute('role','dialog');p.setAttribute('aria-modal','true');p.setAttribute('aria-label','Search and quick navigation');
      p.querySelector('#pal-q').setAttribute('aria-label','Search pages, releases, tasks, bands and artists');
      p.querySelector('#pal-q').setAttribute('aria-keyshortcuts','Control+K Meta+K');
    }
    p.classList.add('open');const q=p.querySelector('#pal-q');q.value='';palSearch();q.focus();
  }
  function closePal(){
    const p=document.getElementById('palette');if(!p?.classList.contains('open'))return;
    p.classList.remove('open');
    const target=paletteReturnFocus?.isConnected?paletteReturnFocus:document.querySelector('.topbar-search,[data-action="search"]');
    paletteReturnFocus=null;if(target instanceof HTMLElement)target.focus({preventScroll:true});
  }
  function rememberPortalView(){
    if(!session||!profile||!view)return;
    const keyMap={profile:'open-discover',discover:'open-discover',editprofile:'settings',builder:'new'};
    const key=keyMap[view]||view;
    const allowed=new Set(['dashboard','pipeline','studio','vault','business','calendar','insights','discography','open-discover','activity','bands','earnings','statements','settings','support','new','roster','operations','notifications','podcasts']);
    if(!allowed.has(key))return;
    try{
      const prior=JSON.parse(sessionStorage.getItem('ie-recent-pages')||'[]');
      const next=[key,...(Array.isArray(prior)?prior:[]).filter(x=>x!==key&&allowed.has(x))].slice(0,5);
      sessionStorage.setItem('ie-recent-pages',JSON.stringify(next));
    }catch(_){}
  }
  function palSearch(){ const q=(document.getElementById('pal-q').value||'').toLowerCase().trim(), out=[];
    const routes=[['dashboard','Overview','Your workspace'],['pipeline','Release pipeline','Track release progress'],['studio','Artist studio','Goals, press kit and release quality'],['vault','File vault','Private documents and working files'],['business','Business suite','Rights, finance, campaigns and integrations'],['calendar','Release calendar','Dates and campaign tasks'],['insights','Insights','Saved catalogue metrics'],['discography','Discography','Browse release records'],['podcasts','Podcast studio','Submit and manage podcast episodes'],['open-discover','Discover artists','Public artist directory'],['activity','Tasks & activity','Open tasks and recent changes'],['notifications','Notifications','Release updates and workspace alerts'],['bands','Bands','Collaborator spaces and invitations'],['earnings','Earnings','Royalties and statements'],['statements','Statements','Financial records'],['settings','Settings & preferences','Profile and preferences'],['support','Help & support','Get help with your workspace'],...(!isAdmin()?[['new','Create a release','Start a release submission']]:[]),...(isAdmin()?[['roster','Roster & invites','Manage artists and label invitations'],['operations','Operations centre','Label operations and review tools']]:[])];
    if(!q){
      try{
        const recent=JSON.parse(sessionStorage.getItem('ie-recent-pages')||'[]');
        const recentRoutes=(Array.isArray(recent)?recent:[]).map(key=>routes.find(route=>route[0]===key)).filter(Boolean).slice(0,3);
        if(recentRoutes.length){out.push('<div class="pal-section-label">RECENT PAGES</div>');recentRoutes.forEach(x=>out.push(`<button class="pal-item pal-recent-item" data-action="${x[0]}"><b>${esc(x[1])}</b><small>Recently visited · ${esc(x[2])}</small></button>`));}
      }catch(_){}
    }
    routes.filter(x=>!q||`${x[1]} ${x[2]}`.toLowerCase().includes(q)).slice(0,q?4:5).forEach(x=>out.push(`<button class="pal-item" data-action="${x[0]}"><b>${esc(x[1])}</b><small>Quick action · ${esc(x[2])}</small></button>`));
    releases.filter(r=>!q||`${r.title} ${r.artist_name}`.toLowerCase().includes(q)).slice(0,6).forEach(r=>out.push(`<button class="pal-item" data-action="open" data-release="${esc(r.id)}"><b>${esc(r.title)}</b><small>Release · ${esc(r.artist_name||'')} · ${esc(r.status)}</small></button>`));
    tasks.filter(t=>!q||`${t.title||''} ${releases.find(r=>String(r.id)===String(t.release_id))?.title||''}`.toLowerCase().includes(q)).slice(0,5).forEach(t=>out.push(`<button class="pal-item" data-action="calendar-task" data-task-id="${esc(t.id)}" data-release="${esc(t.release_id)}"><b>${esc(t.title||'Release task')}</b><small>Task · ${esc(releases.find(r=>String(r.id)===String(t.release_id))?.title||'Release')} · ${t.done?'Complete':'Open'}</small></button>`));
    bands.filter(b=>!q||b.name.toLowerCase().includes(q)).slice(0,4).forEach(b=>out.push(`<button class="pal-item" data-action="goto-band" data-id="${esc(b.id)}"><b>${esc(b.name)}</b><small>Band</small></button>`));
    if(isAdmin()) users.filter(u=>q&&`${u.display_name} ${u.email}`.toLowerCase().includes(q)).slice(0,4).forEach(u=>out.push(`<button class="pal-item" data-action="roster"><b>${esc(u.display_name||u.email)}</b><small>${isAdminRole(u.role)?'Label member':'Artist'} · ${esc(u.email)}</small></button>`));
    document.getElementById('pal-res').innerHTML=out.join('')||'<div class="muted pal-empty">No matches</div>'; bind(); }
  if(!window.__ieStudioShortcuts){window.__ieStudioShortcuts=true;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(session&&profile)openPal();}if(e.key==='Escape'){closePal();}if(e.altKey&&e.key.toLowerCase()==='s'&&session&&profile&&!typing()){e.preventDefault();view='studio';mobile=false;render();}});}
  async function saveProfile(v){ const {error}=await sb.from('profiles').update(v).eq('id',session.user.id); if(error) throw error; Object.assign(profile,v); toast('Profile saved','success'); render(); }
  function modal({title,sub='',fields,ok='Save'}){ return new Promise(res=>{ const o=document.createElement('div'); o.className='palette open modal'; o.setAttribute('role','dialog'); o.setAttribute('aria-modal','true'); o.setAttribute('aria-label',title);
    o.innerHTML=`<div class="palette-box modal-box"><h3>${esc(title)}</h3>${sub?`<p class="muted">${esc(sub)}</p>`:''}${fields.map((f,i)=>`<label class="field"><span>${esc(f.label)}</span>${f.area?`<textarea id="mf${i}" rows="4" maxlength="${f.max||500}" placeholder="${esc(f.ph||'')}">${esc(f.value||'')}</textarea>`:`<input id="mf${i}" maxlength="${f.max||120}" placeholder="${esc(f.ph||'')}" value="${esc(f.value||'')}">`}</label>`).join('')}<div class="row-actions modal-actions"><button class="secondary" data-m="c">Cancel</button><button class="primary" data-m="o">${esc(ok)}</button></div></div>`;
    document.body.appendChild(o); const done=v=>{ o.remove(); res(v); };
    o.querySelector('[data-m="c"]').onclick=()=>done(null);
    o.querySelector('[data-m="o"]').onclick=()=>{ const v=fields.map((f,i)=>o.querySelector('#mf'+i).value.trim()); const bad=fields.findIndex((f,i)=>f.required&&!v[i]); if(bad>=0){ o.querySelector('#mf'+bad).focus(); return; } done(v); };
    o.addEventListener('mousedown',e=>{ if(e.target===o) done(null); }); o.addEventListener('keydown',e=>{ if(e.key==='Escape') done(null); });
    const f=o.querySelector('#mf0'); if(f) f.focus(); }); }
  async function loadBands(){ try{ const b=await sb.from('bands').select('*').order('created_at',{ascending:false}); if(b.error)throw b.error; const m=await sb.from('band_members').select('*, profiles(display_name,email)'); if(m.error)throw m.error; const i=await sb.from('band_invites').select('*').order('created_at',{ascending:false}); if(i.error)throw i.error; const mine=await sb.rpc('my_band_invites'); if(mine.error)throw mine.error; bands=b.data||[];bandMembers=m.data||[];bandInvites=i.data||[];myBandInvites=mine.data||[];setWorkspaceDataWarning('bands',null); }catch(e){ console.warn('Bands unavailable',e); bands=[];bandMembers=[];bandInvites=[];myBandInvites=[];setWorkspaceDataWarning('bands','Band records or memberships could not load. The bands view may be incomplete.'); } }
  function bandsView(){
    const me=session.user.id, ms=b=>bandMembers.filter(m=>m.band_id===b.id), nm=m=>(m.profiles&&(m.profiles.display_name||m.profiles.email))||'Artist';
    const pend=myBandInvites.map(i=>`<div class="band-invite"><div><b>${esc(i.band_name)}</b><span>You've been invited to join this band</span></div><div class="row-actions"><button class="primary" data-action="accept-band" data-id="${esc(i.id)}">Join band</button><button class="secondary" data-action="decline-band" data-id="${esc(i.id)}">Decline</button></div></div>`).join('');
    const cards=bands.map((b,n)=>`<button class="band-card ${b.id===bandId?'active':''}" style="--band-accent:${esc(/^#[0-9a-f]{6}$/i.test(b.accent_color||'')?b.accent_color:'#d7bd72')};animation-delay:${n*60}ms" data-action="open-band" data-id="${esc(b.id)}"><span class="band-art">${b.avatar_path?`<img src="${esc(MEDIA_URL(b.avatar_path))}" alt="">`:esc(b.name.slice(0,2).toUpperCase())}</span><b>${esc(b.name)}</b>${b.tagline?`<span class="band-tagline">${esc(b.tagline)}</span>`:''}<small>${ms(b).length} member${ms(b).length===1?'':'s'} · ${releases.filter(r=>r.band_id===b.id).length} releases</small><div class="stack">${ms(b).slice(0,5).map(m=>`<i>${esc(nm(m).slice(0,1).toUpperCase())}</i>`).join('')}</div></button>`).join('');
    const cur=bands.find(b=>b.id===bandId);
    let det='';
    if(cur){ const owner=isAdmin(); const inv=bandInvites.filter(i=>i.band_id===cur.id&&i.status==='Pending');
      det=`<div class="card invite-card band-detail" style="--band-accent:${esc(/^#[0-9a-f]{6}$/i.test(cur.accent_color||'')?cur.accent_color:'#d7bd72')}">${cur.banner_path?`<img class="band-detail-banner" src="${esc(MEDIA_URL(cur.banner_path))}" alt="">`:''}<div class="panel-title band-detail-head">${cur.avatar_path?`<img class="band-detail-avatar" src="${esc(MEDIA_URL(cur.avatar_path))}" alt="">`:''}<div><p class="eyebrow">BAND PROFILE</p><h2>${esc(cur.name)}</h2>${cur.tagline?`<p class="band-tagline">${esc(cur.tagline)}</p>`:''}<p>${esc(cur.bio||'Add a bio to tell members and collaborators what this band is about.')}</p>${(Array.isArray(cur.links)?cur.links:[]).map(l=>{const u=safeUrl(String(l.url||''));return u?`<a class="pf-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l.label||'Link')} ↗</a>`:''}).join('')}</div></div><div class="roster-list">${ms(cur).map(m=>`<div class="roster-row"><div class="roster-avatar">${esc(nm(m).slice(0,2).toUpperCase())}</div><div class="release-info"><strong>${esc(nm(m))}</strong><span>Member</span></div>${(isAdmin()||m.user_id===me)?`<button class="secondary" data-action="leave-band" data-band="${esc(cur.id)}" data-user="${esc(m.user_id)}">${m.user_id===me?'Leave band':'Remove'}</button>`:''}</div>`).join('')}</div>
      ${owner?`<div class="invite-form band-customise-form" style="margin-top:16px"><h3>Customise this band</h3><div class="band-brand-fields"><label class="field"><span>Band name</span><input id="bnd-edit-name" maxlength="80" value="${esc(cur.name)}"></label><label class="field"><span>Tagline</span><input id="bnd-edit-tagline" maxlength="100" value="${esc(cur.tagline||'')}" placeholder="Independent alt-rock collective"></label><label class="field"><span>Accent colour</span><input id="bnd-edit-accent" type="color" value="${esc(/^#[0-9a-f]{6}$/i.test(cur.accent_color||'')?cur.accent_color:'#d7bd72')}"></label><label class="field"><span>Band photo</span><input id="bnd-edit-avatar" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small>${cur.avatar_path?'Photo uploaded':'Use a square image, up to 2 MB'}</small></label><label class="field"><span>Banner image</span><input id="bnd-edit-banner" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small>${cur.banner_path?'Banner uploaded':'Wide image, up to 2 MB'}</small></label></div>${cur.banner_path?`<img class="band-editor-banner" src="${esc(MEDIA_URL(cur.banner_path))}" alt="Current band banner">`:''}<label class="field"><span>Band bio / identity</span><textarea id="bnd-edit-bio" maxlength="500" rows="3" placeholder="Describe the band's sound, members or purpose">${esc(cur.bio||'')}</textarea></label><label class="field"><span>Social / streaming links (one per line: Label | URL)</span><textarea id="bnd-edit-links" maxlength="1600" rows="4" placeholder="Instagram | https://instagram.com/yourband">${esc((Array.isArray(cur.links)?cur.links:[]).map(l=>`${l.label||'Link'} | ${l.url||''}`).join('\n'))}</textarea></label><button class="primary" data-action="save-band-details" data-id="${esc(cur.id)}">Save band identity</button><hr><label class="field"><span>Invite an artist</span><select id="bi-email"><option value="">Choose an artist...</option>${users.filter(u=>!isAdminRole(u.role)&&!ms(cur).some(m=>m.user_id===u.id)&&!inv.some(i=>i.email.toLowerCase()===String(u.email||'').toLowerCase())).map(u=>`<option value="${esc(u.email)}">${esc(u.display_name||u.email)}</option>`).join('')}</select></label><button class="primary" data-action="invite-band" data-id="${esc(cur.id)}">${icon('plus',15)} Invite</button></div>${inv.map(i=>`<div class="roster-row"><div class="release-info"><strong>${esc(i.email)}</strong><span>Invite sent</span></div><span class="pill neutral">Awaiting reply</span></div>`).join('')}`:''}
      <h3 style="margin:22px 0 10px">Band releases</h3>${releases.filter(r=>r.band_id===cur.id).map(r=>`<div class="roster-row"><div class="release-info"><strong>${esc(r.title)}</strong><span>${esc(r.artist_name||'')}</span></div><span class="pill blue">${esc(r.status)}</span></div>`).join('')||'<p class="sub">No releases yet. Choose this band when you create a release.</p>'}</div>`; }
    return `<section class="page fade"><div class="page-heading"><p class="eyebrow">${isAdmin()?'LABEL':'YOUR GROUPS'}</p><h1>Bands</h1><p class="sub">${isAdmin()?'Build artist collectives: customise identity, invite members and connect releases without sharing anyone’s account.':'Your band is a shared artist identity for members and releases. Your personal account stays yours.'}</p></div>${pend}${isAdmin()?`<div class="card invite-card"><div class="panel-title"><div><h2>Start a band</h2><p>Create the group, then invite artist accounts by email. Members can leave at any time.</p></div></div><div class="invite-form"><label class="field"><span>Band name</span><input id="bnd-name" placeholder="e.g. Neon Static"></label><label class="field"><span>Short bio</span><input id="bnd-bio" placeholder="Optional"></label><button class="primary" data-action="create-band">${icon('plus',15)} Create band</button></div></div>`:''}${cards?`<div class="band-grid">${cards}</div>`:''}${!cards&&!pend&&!isAdmin()?'<p class="sub">You are not in a band yet. The label will invite you when one is set up.</p>':''}${det}</section>`;
  }
  async function loadUsers(){ const {data,error}=await sb.from('profiles').select('*').order('created_at',{ascending:false}); if(error){setWorkspaceDataWarning('users','Artist roster could not load. User management may be incomplete.');throw error;} users=data||[];setWorkspaceDataWarning('users',null); }


  // v30: label operations, delivery ledger and artist-facing royalty statements.
  async function loadOperationsData(){
    if(!isAdmin()){v30Audit=[];v30Deliveries=[];return;}
    const [a,d]=await Promise.all([
      sb.from('release_audit_log').select('id,release_id,actor_id,action,old_status,new_status,details,created_at').order('created_at',{ascending:false}).limit(100),
      sb.from('release_delivery_records').select('*').order('updated_at',{ascending:false}).limit(200)
    ]);
    v30AuditError=a.error?.message||''; v30DeliveryError=d.error?.message||'';
    v30Audit=a.data||[];v30Deliveries=d.data||[];
  }
  async function loadStatementData(){
    const q=sb.from('artist_statements').select('*').order('period_start',{ascending:false});
    const {data,error}=await q.limit(250);v30StatementError=error?.message||'';v30Statements=data||[];
  }
  function operationsView(){
    if(!isAdmin())return '<section class="page"><div class="empty"><h2>Label team only</h2><p>Operations and delivery tracking are available to label administrators.</p></div></section>';
    const audits=v30Audit.map(a=>{const r=releases.find(x=>x.id===a.release_id);return `<div class="tl-item"><i></i><div><b>${esc(String(a.action||'update').replace(/_/g,' '))}</b><p>${esc(r?.artist_name||a.details?.artist_name||'Artist')} · ${esc(r?.title||a.details?.title||'Release')}${a.old_status!==a.new_status&&a.old_status?` · ${esc(a.old_status)} → ${esc(a.new_status||'—')}`:''}</p><small>${dateFmt(String(a.created_at||'').slice(0,10))} ${new Date(a.created_at).toLocaleTimeString(currentLocale(),{hour:'2-digit',minute:'2-digit'})}</small></div></div>`}).join('');
    const deliveries=v30Deliveries.map(d=>{const r=releases.find(x=>x.id===d.release_id);return `<div class="roster-row v30-row"><div class="release-info"><strong>${esc(r?.title||'Release')}</strong><span>${esc(r?.artist_name||'Artist')} · ${esc(d.platform)} · ${esc(d.reference||'No delivery reference')}</span><small>${d.checked_at?'Checked '+dateFmt(String(d.checked_at).slice(0,10)):'Not checked yet'}${d.notes?' · '+esc(d.notes):''}</small></div><span class="pill ${d.delivery_status==='live'?'green':d.delivery_status==='blocked'?'red':d.delivery_status==='accepted'?'blue':'neutral'}">${esc(d.delivery_status)}</span><div class="row-actions">${['planned','sent','accepted','live','blocked'].filter(st=>st!==d.delivery_status).map(st=>`<button class="copy-btn" data-action="delivery-status" data-id="${esc(d.id)}" data-status="${st}">${st==='live'?'Mark live':st==='accepted'?'Accepted':st==='blocked'?'Blocked':st==='sent'?'Mark sent':'Plan'}</button>`).join('')}</div></div>`}).join('');
    const releaseOptions=releases.filter(r=>!['Draft','Rejected'].includes(r.status)).map(r=>`<option value="${esc(r.id)}">${esc(r.artist_name)} — ${esc(r.title)}</option>`).join('');
    const queue=releases.filter(r=>['Submitted','Changes Requested'].includes(r.status)).map(r=>`<div class="roster-row v30-row"><div class="release-info"><strong>${esc(r.artist_name)} — ${esc(r.title)}</strong><span>${esc(r.status)} · Updated ${dateFmt(String(r.updated_at||'').slice(0,10))}</span></div><button class="primary" data-action="open" data-release="${esc(r.id)}">Review</button></div>`).join('');
    const overdue=tasks.filter(t=>!t.done&&t.due_date&&t.due_date<localDateKey()).sort((a,b)=>a.due_date.localeCompare(b.due_date));
    const readiness=releases.filter(r=>!['Rejected'].includes(r.status)).map(r=>{const ts=allTracks.filter(t=>t.release_id===r.id);const checks=[['Release title',String(r.title||'').trim().length>=2],['Artist name',String(r.artist_name||'').trim().length>=2],['Release type',!!r.release_type],['Genre',!!r.genre],['Language',!!r.language],['Territory',!!r.territory],['Store selection',Array.isArray(r.stores)&&r.stores.length>0],['Artwork',!!r.artwork_path],['Release date',!!r.release_date],['UPC',/^\d{12,14}$/.test(r.upc||'')],['Rights',!!r.rights_confirmed],['At least one track',ts.length>0],['Track titles',ts.length>0&&ts.every(t=>String(t.title||'').trim().length>=1)],['Track numbers',ts.length>0&&ts.every(t=>Number.isInteger(Number(t.track_number))&&Number(t.track_number)>0)&&new Set(ts.map(t=>Number(t.track_number))).size===ts.length],['Audio files',ts.length>0&&ts.every(t=>!!t.audio_path)],['Track ISRCs',ts.length>0&&ts.every(t=>/^([A-Z]{2}[A-Z0-9]{3}\d{7})$/.test(t.isrc||''))]];const score=checks.filter(x=>x[1]).length;const missing=checks.filter(x=>!x[1]).map(x=>x[0]);return `<div class="roster-row v30-row"><div class="release-info"><strong>${esc(r.artist_name)} — ${esc(r.title)}</strong><span>${score}/${checks.length} checks complete (${Math.round(score/checks.length*100)}%) · ${esc(r.status)}</span><small>${missing.length?`Needs attention: ${missing.slice(0,5).map(esc).join(', ')}${missing.length>5?` + ${missing.length-5} more`:''}`:'All metadata checks passed'} </small></div><button class="secondary" data-action="open" data-release="${esc(r.id)}">Review release</button></div>`}).join('');
    const todayKey=localDateKey();
    const attention=releases.filter(r=>!['Live','Rejected','Draft'].includes(r.status)).map(r=>{const ts=allTracks.filter(t=>t.release_id===r.id);const missing=[];if(!r.artwork_path)missing.push('artwork');if(!r.release_date)missing.push('release date');if(!/^\d{12,14}$/.test(r.upc||''))missing.push('UPC');if(!r.rights_confirmed)missing.push('rights confirmation');if(!ts.length||!ts.every(t=>!!t.audio_path))missing.push('audio');if(!ts.length||!ts.every(t=>/^([A-Z]{2}[A-Z0-9]{3}\d{7})$/.test(t.isrc||'')))missing.push('ISRCs');const review=['Submitted','Changes Requested'].includes(r.status);const datePast=!!r.release_date&&r.release_date<todayKey&&r.status!=='Live';const rank=review?0:datePast?1:missing.length?2:3;return {r,missing,review,datePast,rank,updated:String(r.updated_at||r.created_at||'').slice(0,10)}}).filter(x=>x.review||x.datePast||x.missing.length).sort((a,b)=>a.rank-b.rank||a.updated.localeCompare(b.updated)).slice(0,10);
    const attentionRows=attention.map(x=>{const label=x.review?(x.r.status==='Submitted'?'Awaiting label review':'Artist changes requested'):x.datePast?'Release date has passed':'Metadata incomplete';const detail=x.review?`Updated ${dateFmt(x.updated)}`:x.datePast?`Scheduled ${dateFmt(x.r.release_date)}`:`Missing ${x.missing.slice(0,3).join(', ')}${x.missing.length>3?' + '+(x.missing.length-3)+' more':''}`;return `<div class="roster-row v114-attention-row"><span class="v114-priority-mark ${x.rank===0?'urgent':x.rank===1?'late':'check'}" aria-hidden="true"></span><div class="release-info"><strong>${esc(x.r.artist_name||'Artist')} — ${esc(x.r.title||'Untitled release')}</strong><span>${esc(label)} · ${esc(x.r.status)}</span><small>${esc(detail)}</small></div><button class="${x.review?'primary':'secondary'}" data-action="open" data-release="${esc(x.r.id)}">${x.review?'Review':'Resolve'}</button></div>`}).join('');
    return `<section class="page fade"><div class="page-heading"><p class="eyebrow">LABEL WORKSPACE</p><h1>Operations centre</h1><p class="sub">Release readiness, distributor delivery records and an automatic release change history. Delivery statuses are your team's manual records; they do not query distributors.</p></div><div class="metrics"><div class="metric"><span>Active releases</span><strong>${releases.filter(r=>!['Live','Rejected','Draft'].includes(r.status)).length}</strong><small>In the release pipeline</small></div><div class="metric"><span>Awaiting review</span><strong>${releases.filter(r=>['Submitted','Changes Requested'].includes(r.status)).length}</strong><small>Approval queue</small></div><div class="metric"><span>Overdue tasks</span><strong>${overdue.length}</strong><small>Campaign deadlines passed</small></div><div class="metric"><span>Audit entries</span><strong>${v30Audit.length}</strong><small>Most recent 100</small></div></div>
      ${portalHealthPanel()}<div class="card v30-panel v114-attention-panel"><div class="section-head"><div><p class="eyebrow">PRIORITY TRIAGE</p><h2>Needs attention first</h2></div><span class="pill ${attention.length?'amber':'green'}">${attention.length} item${attention.length===1?'':'s'}</span></div><p class="muted">Review requests come first, then past release dates, then incomplete metadata. This is based on saved portal records, not live distributor checks.</p>${attentionRows||'<p class="muted">Nothing urgent in the active pipeline. Keep an eye on upcoming dates and new submissions.</p>'}</div><div class="card v30-panel"><div class="section-head"><h2>Approval queue</h2><span class="muted">Submitted and changes requested</span></div>${queue||'<p class="muted">No releases waiting for review.</p>'}</div>
      <div class="card v30-panel"><div class="section-head"><h2>Overdue campaign alerts</h2><span class="muted">Open tasks past due date</span></div>${overdue.length?overdue.map(t=>taskRow(t,true)).join(''):'<p class="muted">No overdue campaign tasks.</p>'}</div>
      <div class="card v30-panel"><div class="section-head"><h2>Release quality checker</h2><button class="secondary" data-action="export-readiness">Export checklist CSV</button></div><p class="muted">Checks metadata completeness only; it cannot guarantee distributor acceptance or audio mastering quality.</p>${readiness||'<p class="muted">No releases to check.</p>'}</div>
      <div class="card v30-panel"><div class="section-head"><h2>Delivery log</h2></div>${v30DeliveryError?`<div class="error-box">Delivery records unavailable: ${esc(v30DeliveryError)}. Apply the v30 migration and refresh.</div>`:''}<div class="invite-form v30-form"><label class="field"><span>Release</span><select id="v30-del-release"><option value="">Choose a release…</option>${releaseOptions}</select></label><label class="field"><span>Store / distributor</span><input id="v30-del-platform" maxlength="80" placeholder="e.g. Spotify"></label><label class="field"><span>Reference / ticket</span><input id="v30-del-reference" maxlength="160" placeholder="Optional reference ID"></label><label class="field"><span>Initial status</span><select id="v30-del-status"><option value="planned">Planned</option><option value="sent">Sent</option><option value="accepted">Accepted</option><option value="live">Live</option><option value="blocked">Blocked</option></select></label><label class="field"><span>Notes</span><input id="v30-del-notes" maxlength="500" placeholder="Optional internal note"></label><button class="primary" data-action="delivery-create">Add delivery record</button></div>${deliveries||'<p class="muted">No delivery records yet. Add one after a release has been approved.</p>'}</div>
      <div class="card v30-panel"><div class="section-head"><h2>Release audit trail</h2><span class="muted">Latest 100 changes</span></div>${v30AuditError?`<p class="muted">Audit history unavailable: ${esc(v30AuditError)}</p>`:''}<div class="timeline">${audits||'<p class="muted">No audit entries yet. New release inserts and meaningful metadata/status changes are recorded automatically.</p>'}</div></div></section>`;
  }
  function statementsView(){
    const own=v30Statements.filter(x=>isAdmin()||x.artist_id===session.user.id);
    const visible=own.filter(x=>isAdmin()||['published','paid'].includes(x.status));
    const total=visible.reduce((n,x)=>n+Number(x.net_amount||0),0);
    const people=users.filter(u=>!isAdminRole(u.role));
    const options=people.map(u=>`<option value="${esc(u.id)}">${esc(u.display_name||u.full_name||u.email||u.id)}</option>`).join('');
    const rows=visible.map(x=>{const u=users.find(z=>z.id===x.artist_id);return `<div class="roster-row v30-row"><div class="release-info"><strong>${esc(x.statement_number||'Statement')} ${isAdmin()?'· '+esc(u?.display_name||u?.email||'Artist'):''}</strong><span>${esc(x.period_start)} — ${esc(x.period_end)} · ${esc(x.currency)}</span><small>${x.note?esc(x.note):'Royalty statement'}${x.paid_at?' · Paid '+dateFmt(String(x.paid_at).slice(0,10)):''}</small></div><div class="statement-amount"><strong>${formatNumber(x.net_amount,{minimumFractionDigits:2,maximumFractionDigits:2})} ${esc(x.currency)}</strong><span class="pill ${x.status==='paid'?'green':x.status==='published'?'blue':'neutral'}">${esc(x.status)}</span></div>${isAdmin()?`<div class="row-actions">${x.status==='draft'?`<button class="secondary" data-action="statement-status" data-id="${esc(x.id)}" data-status="published">Publish to artist</button>`:''}${x.status==='published'?`<button class="secondary" data-action="statement-status" data-id="${esc(x.id)}" data-status="paid">Mark paid</button>`:''}${x.status!=='draft'?`<button class="copy-btn" data-action="statement-status" data-id="${esc(x.id)}" data-status="draft">Unpublish</button>`:''}<button class="copy-btn" data-action="statement-delete" data-id="${esc(x.id)}">Delete</button>`:''}</div>`}).join('');
    return `<section class="page fade"><div class="page-heading"><p class="eyebrow">FINANCE</p><h1>Artist statements</h1><p class="sub">Create a period statement, publish it securely to the artist's account, and record payment. These are label-entered records, not a bank feed or tax document.</p></div><div class="metrics"><div class="metric"><span>${isAdmin()?'Visible statements':'Published statements'}</span><strong>${visible.length}</strong><small>For this account view</small></div><div class="metric"><span>${isAdmin()?'Published / paid total':'Your net total'}</span><strong>${formatNumber(total,{minimumFractionDigits:2,maximumFractionDigits:2})}</strong><small>Mixed currencies are shown as a simple total; export/filter by currency before reconciliation.</small></div><div class="metric"><span>Awaiting payment</span><strong>${visible.filter(x=>x.status==='published').length}</strong><small>Published, not marked paid</small></div></div>
    ${isAdmin()?`<div class="card v30-panel"><h2>Create statement</h2><p class="muted">Draft statements are visible only to label admins. Publishing makes the statement available to that artist.</p><div class="invite-form v30-form"><label class="field"><span>Artist</span><select id="v30-st-artist"><option value="">Choose an artist…</option>${options}</select></label><label class="field"><span>Period start</span><input id="v30-st-start" type="date"></label><label class="field"><span>Period end</span><input id="v30-st-end" type="date"></label><label class="field"><span>Statement number</span><input id="v30-st-number" maxlength="80" placeholder="Optional unique reference"></label><label class="field"><span>Currency</span><select id="v30-st-currency"><option value="GBP">GBP (£)</option><option value="USD">USD ($)</option><option value="EUR">EUR (€)</option></select></label><label class="field"><span>Gross amount</span><input id="v30-st-gross" type="number" min="0" step="0.01" value="0"></label><label class="field"><span>Adjustments (+/-)</span><input id="v30-st-adjust" type="number" step="0.01" value="0"></label><label class="field"><span>Net amount (calculated)</span><input id="v30-st-net" type="number" step="0.01" value="0" readonly aria-describedby="v30-st-net-help"><small id="v30-st-net-help" class="muted">Gross plus adjustments, rounded to the nearest penny.</small></label><label class="field"><span>Artist-facing note</span><input id="v30-st-note" maxlength="500" placeholder="Optional note for the artist"></label><button class="primary" data-action="statement-create">Save draft</button></div></div>`:''}
    <div class="card v30-panel"><div class="section-head"><h2>${isAdmin()?'Statement register':'Your statements'}</h2><button class="secondary" data-action="statement-export">Export CSV</button></div>${v30StatementError?`<div class="error-box">Statements unavailable: ${esc(v30StatementError)}. Apply the v30 migration and refresh.</div>`:''}${rows||'<div class="empty"><h3>No statements yet</h3><p>Published statements will appear here when the label adds them.</p></div>'}</div></section>`;
  }
